public class InnerConnectionRedshiftPropertiesInputFactory(Action<Humidifier.DataZone.ConnectionTypes.RedshiftPropertiesInput> factoryAction = null) : SubResourceFactory<Humidifier.DataZone.ConnectionTypes.RedshiftPropertiesInput>
{

    internal InnerConnectionRedshiftStoragePropertiesFactory StorageFactory { get; set; }

    internal InnerConnectionRedshiftCredentialsFactory CredentialsFactory { get; set; }

    internal InnerConnectionRedshiftLineageSyncConfigurationInputFactory LineageSyncFactory { get; set; }

    protected override Humidifier.DataZone.ConnectionTypes.RedshiftPropertiesInput Create()
    {
        var redshiftPropertiesInputResult = CreateRedshiftPropertiesInput();
        factoryAction?.Invoke(redshiftPropertiesInputResult);

        return redshiftPropertiesInputResult;
    }

    private Humidifier.DataZone.ConnectionTypes.RedshiftPropertiesInput CreateRedshiftPropertiesInput()
    {
        var redshiftPropertiesInputResult = new Humidifier.DataZone.ConnectionTypes.RedshiftPropertiesInput();

        return redshiftPropertiesInputResult;
    }
    public override void CreateChildren(Humidifier.DataZone.ConnectionTypes.RedshiftPropertiesInput result)
    {
        base.CreateChildren(result);

        result.Storage ??= StorageFactory?.Build();
        result.Credentials ??= CredentialsFactory?.Build();
        result.LineageSync ??= LineageSyncFactory?.Build();
    }

} // End Of Class

